// Applied rules: [C1, C3]
// Skipped rules: [C3.S1: Changing `xmlRegFreeState` from raw pointer style to references would require caller-wide audit and offers little leverage for this tiny deallocation routine; prefer local hoisting.]
fn xmlRegFreeState(mut state: xmlRegStatePtr) { unsafe {
    if state.is_null() {
        return;
    }
    let trans = (*state).trans;
    let trans_to = (*state).transTo;
    // SAFETY: allocator hooks are initialized in this build; c2rust's Option callback is known Some at these free call sites.
    let xml_free = unsafe { xmlFree.unwrap_unchecked() };
    if !trans.is_null() {
        xml_free(trans as *mut c_void);
    }
    if !trans_to.is_null() {
        xml_free(trans_to as *mut c_void);
    }
    xml_free(state as *mut c_void);
} }

